export type Lang = 'it' | 'en' | 'es' | 'fr' | 'de' | 'pt'
const SUPPORTED = ['it', 'en', 'es', 'fr', 'de', 'pt']

// Lingua dell'interfaccia di Kiro Crew: il dashboard la scrive in <html lang>.
export const crewLangCode = (): string => {
  try { return document.documentElement.lang || navigator.language || 'en' } catch { return 'en' }
}
export function resolveLang(raw: string): Lang {
  const two = raw.slice(0, 2).toLowerCase()
  return (SUPPORTED.includes(two) ? two : 'en') as Lang
}

